```python
import urllib.request
from bs4 import BeautifulSoup
import csv
import os

# Constants
CSV_FILE_PATH = 'scraped_data.csv'


def task_func(url):
    def clean_text(value):
        return " ".join(str(value).split())

    def normalize_row(row, width):
        values = [clean_text(cell) for cell in row]
        if len(values) < width:
            values.extend([""] * (width - len(values)))
        return values[:width]

    def make_headers(headers, width):
        headers = [clean_text(h) for h in headers[:width]]
        if len(headers) < width:
            headers.extend([""] * (width - len(headers)))

        result = []
        seen = set()
        for idx, name in enumerate(headers, start=1):
            if not name:
                name = f"column_{idx}"
            candidate = name
            suffix = 2
            while candidate in seen:
                candidate = f"{name}_{suffix}"
                suffix += 1
            seen.add(candidate)
            result.append(candidate)
        return result

    def write_csv(headers, rows):
        width = max([len(headers)] + [len(row) for row in rows]) if (headers or rows) else 1
        headers = make_headers(headers, width)
        rows = [normalize_row(row, width) for row in rows]

        with open(CSV_FILE_PATH, "w", newline="", encoding="utf-8") as f:
            writer = csv.writer(f)
            writer.writerow(headers)
            writer.writerows(rows)

    def extract_table_rows(table):
        rows = []
        for tr in table.find_all("tr"):
            if tr.find_parent("table") is not table:
                continue
            cells = tr.find_all(["th", "td"], recursive=False)
            if not cells:
                continue
            values = [clean_text(cell.get_text(" ", strip=True)) for cell in cells]
            if any(values):
                rows.append(values)
        return rows

    try:
        if not url or not str(url).strip():
            write_csv(["error"], [["Empty URL provided"]])
            return CSV_FILE_PATH

        request = urllib.request.Request(
            url,
            headers={
                "User-Agent": "Mozilla/5.0 (compatible; CodexScraper/1.0)",
                "Accept": "text/html,application/xhtml+xml,application/xml;q=0.9,*/*;q=0.8",
            },
        )

        with urllib.request.urlopen(request, timeout=15) as response:
            charset = None
            if hasattr(response.headers, "get_content_charset"):
                charset = response.headers.get_content_charset()
            html = response.read().decode(charset or "utf-8", errors="replace")

        soup = BeautifulSoup(html, "html.parser")

        best_table = None
        best_table_rows = []
        best_score = (-1, -1)

        for table in soup.find_all("table"):
            rows = extract_table_rows(table)
            if not rows:
                continue
            score = (len(rows), max(len(r) for r in rows))
            if score > best_score:
                best_score = score
                best_table = table
                best_table_rows = rows

        if best_table_rows and best_table is not None:
            first_tr = next(
                (
                    tr
                    for tr in best_table.find_all("tr")
                    if tr.find_parent("table") is best_table
                    and tr.find_all(["th", "td"], recursive=False)
                ),
                None,
            )
            has_header = bool(first_tr and first_tr.find_all("th", recursive=False))

            if has_header:
                headers = best_table_rows[0]
                data_rows = best_table_rows[1:]
            else:
                headers = [f"column_{i}" for i in range(1, best_score[1] + 1)]
                data_rows = best_table_rows

            write_csv(headers, data_rows)
            return CSV_FILE_PATH

        block_tags = ["h1", "h2", "h3", "h4", "h5", "h6", "p", "li", "blockquote", "pre"]
        seen = set()
        rows = []

        for tag in soup.find_all(block_tags):
            text = clean_text(tag.get_text(" ", strip=True))
            if text and text not in seen:
                seen.add(text)
                rows.append([text])

        if not rows:
            title = clean_text(soup.title.get_text(" ", strip=True)) if soup.title and soup.title.get_text(strip=True) else ""
            if title:
                rows = [[title]]
            else:
                page_text = clean_text(soup.get_text(" ", strip=True))
                rows = [[page_text]] if page_text else [[""]]

        write_csv(["text"], rows)
        return CSV_FILE_PATH

    except Exception as exc:
        try:
            with open(CSV_FILE_PATH, "w", newline="", encoding="utf-8") as f:
                writer = csv.writer(f)
                writer.writerow(["error"])
                writer.writerow([clean_text(exc)])
        except Exception:
            pass
        return CSV_FILE_PATH
